commit c263569fbacc3efcbfe7154a556757bdc7b21682
Author: Nick Hung <nick@andestech.com>
Date:   Mon Jun 8 09:46:39 2026 +0800

    target/riscv: allow debugger writes to vl/vtype CSRs

    vl (CSR 0xC20) and vtype (CSR 0xC21) are architecturally read-only
    CSRs -- the spec only allows setting them via vsetvl/vsetvli.
    The gdbstub handback path needs to restore saved values via P-packets
    (for the hybrid QEMU->vsim->QEMU2 round-trip).

    Two changes:
    - write_vl / write_vtype: direct env->vl / env->vtype writes, with
      vill extracted from the MSB of the packed vtype representation.
    - riscv_csrrw_check: skip the read-only gate when env->debugger is
      set (same flag already used for other debug-mode CSR overrides).

    Co-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>

diff --git a/target/riscv/csr.c b/target/riscv/csr.c
index a1328ea264..e60987967c 100644
--- a/target/riscv/csr.c
+++ b/target/riscv/csr.c
@@ -864,6 +864,33 @@ static RISCVException read_vlenb(CPURISCVState *env, int csrno,
     return RISCV_EXCP_NONE;
 }

+/* Debug-mode writes: restore saved vl/vtype (used by hybrid gdbstub handback).
+ * vill is packed in the MSB of the architectural vtype register. */
+static RISCVException write_vl(CPURISCVState *env, int csrno,
+                               target_ulong val)
+{
+    env->vl = val;
+    return RISCV_EXCP_NONE;
+}
+
+static RISCVException write_vtype(CPURISCVState *env, int csrno,
+                                  target_ulong val)
+{
+    switch (env->xl) {
+    case MXL_RV32:
+        env->vill  = (val >> 31) & 1;
+        env->vtype = val & ~(target_ulong)(1u << 31);
+        break;
+    case MXL_RV64:
+        env->vill  = (val >> 63) & 1;
+        env->vtype = val & ~(uint64_t)(1ULL << 63);
+        break;
+    default:
+        g_assert_not_reached();
+    }
+    return RISCV_EXCP_NONE;
+}
+
 static RISCVException read_vxrm(CPURISCVState *env, int csrno,
                                 target_ulong *val)
 {
@@ -4920,8 +4947,10 @@ static inline RISCVException riscv_csrrw_check(CPURISCVState *env,
         return RISCV_EXCP_ILLEGAL_INST;
     }

-    /* read / write check */
-    if (write && read_only) {
+    /* read / write check -- debugger bypasses the read-only gate so that
+     * gdbstub P-packets can restore saved vl/vtype (and other arch-read-only
+     * CSRs) during hybrid handback. */
+    if (write && read_only && !env->debugger) {
         return RISCV_EXCP_ILLEGAL_INST;
     }

@@ -5196,8 +5225,8 @@ riscv_csr_operations csr_ops[CSR_TABLE_SIZE] = {
     [CSR_VXSAT]    = { "vxsat",    vs,     read_vxsat,   write_vxsat  },
     [CSR_VXRM]     = { "vxrm",     vs,     read_vxrm,    write_vxrm   },
     [CSR_VCSR]     = { "vcsr",     vs,     read_vcsr,    write_vcsr   },
-    [CSR_VL]       = { "vl",       vs,     read_vl                    },
-    [CSR_VTYPE]    = { "vtype",    vs,     read_vtype                 },
+    [CSR_VL]       = { "vl",       vs,     read_vl,    write_vl    },
+    [CSR_VTYPE]    = { "vtype",    vs,     read_vtype, write_vtype },
     [CSR_VLENB]    = { "vlenb",    vs,     read_vlenb                 },
     /* User Timers and Counters */
     [CSR_CYCLE]    = { "cycle",    ctr,    read_hpmcounter  },

