/* SimControl write handler. Interprets writes to offset 0:
 *   value < 256          → raw exit code (used by vplat _exit()).
 *   0x01234567/68/71     → exit 0  (FINISHED / PASSED / SKIPPED)
 *   0x01234569/70        → exit 1  (FAILED / WARNING) */
static void sim_ctrl_write(void *opaque, hwaddr offset,
                           uint64_t val, unsigned size)
{
    (void)opaque; (void)size;
    if (offset != 0) {
        return;
    }
    int code;
    if (val < 256) {
        code = (int)(uint32_t)val;
    } else if (val == 0x01234567 || val == 0x01234568 || val == 0x01234571) {
        code = 0;
    } else if (val == 0x01234569 || val == 0x01234570) {
        code = 1;
    } else {
        return;
    }
    exit(code);
}

